mapper.select:
SELECT s.*, e.name AS event_name, e.score_unit AS score_unit, e.score_type AS score_type, m.name AS meeting_name FROM t_score s LEFT JOIN t_event e ON s.event_id = e.id LEFT JOIN t_meeting m ON s.meeting_id = m.id WHERE s.deleted = 0
AND s.meeting_id = #{meetingId}
AND s.event_id = #{eventId}
AND s.user_id = #{userId}
AND s.status = #{status}
ORDER BY s.event_id ASC, s.ranking ASC

SELECT e.name AS event_name, e.category, COUNT(*) AS score_count, MIN(s.score_value) AS min_score, MAX(s.score_value) AS max_score, AVG(s.score_value) AS avg_score FROM t_score s LEFT JOIN t_event e ON s.event_id = e.id WHERE s.deleted = 0 AND s.status >= 1
AND s.meeting_id = #{meetingId}
GROUP BY s.event_id, e.name, e.category ORDER BY e.category, e.name

SELECT s.user_id, SUM(s.points) AS total_points, SUM(CASE WHEN s.ranking = 1 THEN 1 ELSE 0 END) AS gold, SUM(CASE WHEN s.ranking = 2 THEN 1 ELSE 0 END) AS silver, SUM(CASE WHEN s.ranking = 3 THEN 1 ELSE 0 END) AS bronze FROM t_score s WHERE s.deleted = 0 AND s.status >= 2
AND s.meeting_id = #{meetingId}
GROUP BY s.user_id

SELECT s.user_id, SUM(s.points) AS total_points, COUNT(*) AS event_count, SUM(CASE WHEN s.ranking = 1 THEN 1 ELSE 0 END) AS gold, SUM(CASE WHEN s.ranking = 2 THEN 1 ELSE 0 END) AS silver, SUM(CASE WHEN s.ranking = 3 THEN 1 ELSE 0 END) AS bronze FROM t_score s WHERE s.deleted = 0 AND s.status >= 2
AND s.meeting_id = #{meetingId}
GROUP BY s.user_id ORDER BY total_points DESC, gold DESC LIMIT #{limit}
